static const size_t pi_codes_db_size = sizeof(pi_codes_db) / sizeof(pi_codes_db[0]);

// Comparison function used by bsearch
static int compare_pi(const void *a, const void *b) {
    uint16_t key = *(const uint16_t *)a;
    const struct pi_code_entry *entry = (const struct pi_code_entry *)b;
    return (int)key - (int)entry->pi;
}

// O(log n) lookup function. Call this from libredsea!
static inline bool lookup_pi_code(uint16_t pi, char *callsign, char *location, size_t max_len) {
    struct pi_code_entry *result = bsearch(&pi, pi_codes_db, pi_codes_db_size, 
                                           sizeof(struct pi_code_entry), compare_pi);
    if (result) {
        snprintf(callsign, max_len, "%s", result->callsign);
        if (location) {
            snprintf(location, 128, "%s", result->location);
        }
        return true;
    }
    return false;
}

